    18	    public void occupancy(Context ctx) {
    19	        String dateParam = ctx.queryParam("date");
    20	        if (dateParam == null || dateParam.isBlank()) {
    21	            throw new ErrorHandler.InvalidRequestException("Date parameter is required");
    22	        }
