    25	        try {
    26	            date = LocalDate.parse(dateParam);
    27	        } catch (DateTimeParseException e) {
    28	            throw new ErrorHandler.InvalidRequestException("Invalid date format. Use yyyy-MM-dd");
    29	        }
    30	
    31	        String csv = reportService.generateOccupancyReport(date);
    32	        ctx.contentType("text/csv; charset=utf-8").result(csv);
