     9	import com.marealta.domain.repository.RoomRepository;
    10	import com.marealta.domain.service.ReservationService;
    11	import io.javalin.http.Context;
    12	import io.javalin.http.HttpStatus;
    13	
    14	import java.time.LocalDate;
    15	import java.time.format.DateTimeParseException;
    16	
    17	public class ReservationController {
    18	    private final ReservationService reservationService;
    19	    private final ReservationRepository reservationRepository;
    20	
    21	    public ReservationController(ReservationService reservationService, ReservationRepository reservationRepository) {
    22	        this.reservationService = reservationService;
    23	        this.reservationRepository = reservationRepository;
    24	    }
    25	
    26	    public void create(Context ctx) {
    27	        CreateReservationRequest request;
    28	        try {
    29	            request = ctx.bodyAsClass(CreateReservationRequest.class);
    30	        } catch (Exception e) {
    31	            throw new ErrorHandler.InvalidRequestException("Invalid request body");
    32	        }
    33	
    34	        validateRequest(request);
    35	
    36	        Reservation reservation = reservationService.createReservation(
    37	            request.roomNumber(),
    38	            request.guestName(),
    39	            request.guestEmail(),
    40	            request.guestCpf(),
    41	            request.checkIn(),
    42	            request.checkOut(),
    43	            request.guests(),
    44	            request.ratePlan()
    45	        );
    46	
    47	        ctx.status(HttpStatus.CREATED).json(ReservationResponse.from(reservation));
    48	    }
    49	
    50	    public void get(Context ctx) {
    51	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    52	        Reservation reservation = reservationRepository.findById(id)
    53	            .orElseThrow(() -> new ReservationService.ReservationNotFoundException(id));
    54	        ctx.json(ReservationResponse.from(reservation));
    55	    }
    56	
    57	    public void confirm(Context ctx) {
    58	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    59	        Reservation reservation = reservationService.confirmReservation(id);
    60	        ctx.json(ReservationResponse.from(reservation));
    61	    }
    62	
    63	    public void cancel(Context ctx) {
    64	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    65	        Reservation reservation = reservationService.cancelReservation(id);
    66	        ctx.json(ReservationResponse.from(reservation));
    67	    }
    68	
    69	    public void checkIn(Context ctx) {
    70	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    71	        Reservation reservation = reservationService.checkIn(id);
    72	        ctx.json(ReservationResponse.from(reservation));
    73	    }
    74	
    75	    public void checkOut(Context ctx) {
    76	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    77	        Reservation reservation = reservationService.checkOut(id);
    78	        String roomType = getRoomType(reservation.getRoomNumber());
    79	        ctx.json(DocumentResponse.from(reservation, roomType));
    80	    }
    81	
    82	    public void getDocument(Context ctx) {
    83	        Long id = ctx.pathParamAsClass("id", Long.class).get();
    84	        Reservation reservation = reservationRepository.findById(id)
    85	            .orElseThrow(() -> new ReservationService.ReservationNotFoundException(id));
    86	
    87	        if (!reservation.isPaid()) {
    88	            throw new ReservationService.OperationNotAllowedException(
    89	                "Document is only available for paid reservations"
    90	            );
    91	        }
    92	
    93	        String roomType = getRoomType(reservation.getRoomNumber());
    94	        ctx.json(DocumentResponse.from(reservation, roomType));
    95	    }
    96	
    97	    private void validateRequest(CreateReservationRequest request) {
    98	        if (request.roomNumber() == null || request.roomNumber().isBlank()) {
    99	            throw new ErrorHandler.InvalidRequestException("Room number is required");
   100	        }
   101	        if (request.guestName() == null || request.guestName().isBlank()) {
   102	            throw new ErrorHandler.InvalidRequestException("Guest name is required");
   103	        }
   104	        if (request.guestEmail() == null || request.guestEmail().isBlank()) {
   105	            throw new ErrorHandler.InvalidRequestException("Guest email is required");
   106	        }
   107	        if (request.guestCpf() == null || request.guestCpf().isBlank()) {
   108	            throw new ErrorHandler.InvalidRequestException("Guest CPF is required");
   109	        }
   110	        if (request.checkIn() == null) {
   111	            throw new ErrorHandler.InvalidRequestException("Check-in date is required");
   112	        }
   113	        if (request.checkOut() == null) {
   114	            throw new ErrorHandler.InvalidRequestException("Check-out date is required");
   115	        }
   116	        if (!request.checkOut().isAfter(request.checkIn())) {
   117	            throw new ErrorHandler.InvalidRequestException("Check-out must be after check-in");
   118	        }
   119	        if (request.ratePlan() == null) {
   120	            throw new ErrorHandler.InvalidRequestException("Rate plan is required");
   121	        }
   122	    }
   123	
   124	    private String getRoomType(String roomNumber) {
   125	        return switch (roomNumber) {
   126	            case "101", "102" -> "STANDARD";
   127	            case "201", "202" -> "DELUXE";
   128	            case "301" -> "SUITE";
   129	            default -> "";
   130	        };
   131	    }
   132	}
