     1	package com.marealta.api.error;
     2	
     3	import com.marealta.domain.service.ReservationService;
     4	import io.javalin.http.Context;
     5	import io.javalin.http.HttpStatus;
     6	
     7	public class ErrorHandler {
     8	
     9	    public static void handle(Exception e, Context ctx) {
    10	        if (e instanceof ReservationService.RoomNotFoundException) {
    11	            ctx.status(HttpStatus.NOT_FOUND)
    12	               .json(new ErrorResponse("ROOM_NOT_FOUND", e.getMessage()));
    13	        } else if (e instanceof ReservationService.ReservationNotFoundException) {
    14	            ctx.status(HttpStatus.NOT_FOUND)
    15	               .json(new ErrorResponse("RESERVATION_NOT_FOUND", e.getMessage()));
    16	        } else if (e instanceof ReservationService.RoomUnavailableException) {
    17	            ctx.status(HttpStatus.CONFLICT)
    18	               .json(new ErrorResponse("ROOM_UNAVAILABLE", e.getMessage()));
    19	        } else if (e instanceof ReservationService.OperationNotAllowedException) {
    20	            ctx.status(HttpStatus.CONFLICT)
    21	               .json(new ErrorResponse("OPERATION_NOT_ALLOWED", e.getMessage()));
    22	        } else if (e instanceof ReservationService.CapacityExceededException) {
    23	            ctx.status(HttpStatus.UNPROCESSABLE_CONTENT)
    24	               .json(new ErrorResponse("CAPACITY_EXCEEDED", e.getMessage()));
    25	        } else if (e instanceof ReservationService.InvalidRequestException) {
    26	            ctx.status(HttpStatus.BAD_REQUEST)
    27	               .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    28	        } else if (e instanceof InvalidRequestException) {
    29	            ctx.status(HttpStatus.BAD_REQUEST)
    30	               .json(new ErrorResponse("INVALID_REQUEST", e.getMessage()));
    31	        } else {
    32	            ctx.status(HttpStatus.INTERNAL_SERVER_ERROR)
    33	               .json(new ErrorResponse("INTERNAL_ERROR", "An unexpected error occurred"));
    34	        }
    35	    }
    36	
    37	    public static class InvalidRequestException extends RuntimeException {
    38	        public InvalidRequestException(String message) {
    39	            super(message);
    40	        }
    41	    }
    42	}
