     1	package com.marealta.domain.service;
     2	
     3	import com.marealta.domain.model.RatePlan;
     4	import com.marealta.domain.model.Room;
     5	
     6	import java.math.BigDecimal;
     7	import java.math.RoundingMode;
     8	import java.time.LocalDate;
     9	import java.time.Month;
    10	
    11	public class PricingService {
    12	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
    13	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
    14	
    15	    public BigDecimal calculateNightPrice(Room room, LocalDate night) {
    16	        BigDecimal baseRate = room.getNightlyRate();
    17	        if (isHighSeason(night)) {
    18	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER)
    19	                .setScale(2, RoundingMode.HALF_EVEN);
    20	        }
    21	        return baseRate;
    22	    }
    23	
    24	    public BigDecimal calculateSubtotal(Room room, LocalDate checkIn, LocalDate checkOut) {
    25	        BigDecimal subtotal = BigDecimal.ZERO;
    26	        LocalDate current = checkIn;
    27	
    28	        while (current.isBefore(checkOut)) {
    29	            BigDecimal nightPrice = calculateNightPrice(room, current);
    30	            subtotal = subtotal.add(nightPrice);
    31	            current = current.plusDays(1);
    32	        }
    33	
    34	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    35	    }
    36	
    37	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
    38	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
    39	            return subtotal.multiply(NON_REFUNDABLE_DISCOUNT)
    40	                .setScale(2, RoundingMode.HALF_EVEN);
    41	        }
    42	        return BigDecimal.ZERO;
    43	    }
    44	
    45	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    46	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    47	    }
    48	
    49	    private boolean isHighSeason(LocalDate date) {
    50	        Month month = date.getMonth();
    51	        int day = date.getDayOfMonth();
    52	
    53	        if (month == Month.JULY) {
    54	            return true;
    55	        }
    56	
    57	        if (month == Month.DECEMBER && day >= 15) {
    58	            return true;
    59	        }
    60	
    61	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    62	            return true;
    63	        }
    64	
    65	        return false;
    66	    }
    67	}
