    17	public class ReportService {
    18	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    19	
    20	    private final ReservationRepository reservationRepository;
    21	    private final RoomRepository roomRepository;
    22	
    23	    public ReportService(ReservationRepository reservationRepository, RoomRepository roomRepository) {
    24	        this.reservationRepository = reservationRepository;
