    27	
    28	    public String generateOccupancyReport(LocalDate night) {
    29	        List<Reservation> reservations = reservationRepository.findByNight(night);
    30	        List<Room> allRooms = roomRepository.findAll();
    31	
    32	        Map<String, Room> roomMap = allRooms.stream()
    33	            .collect(Collectors.toMap(Room::getNumber, r -> r));
    34	
    35	        StringBuilder csv = new StringBuilder();
    36	        csv.append("room,type,reservation,check_in,check_out\n");
    37	
    38	        for (Reservation reservation : reservations) {
    39	            Room room = roomMap.get(reservation.getRoomNumber());
