    17	public class ReservationService {
    18	    private final ReservationRepository reservationRepository;
    19	    private final RoomRepository roomRepository;
    20	    private final PricingService pricingService;
    21	    private final EventDispatcher eventDispatcher;
    22	
    23	    public ReservationService(ReservationRepository reservationRepository,
    24	                            RoomRepository roomRepository,
    25	                            PricingService pricingService,
    26	                            EventDispatcher eventDispatcher) {
    27	        this.reservationRepository = reservationRepository;
    28	        this.roomRepository = roomRepository;
    29	        this.pricingService = pricingService;
    30	        this.eventDispatcher = eventDispatcher;
    31	    }
    32	
    33	    public Reservation createReservation(String roomNumber, String guestName, String guestEmail,
    34	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    35	                                        int guests, RatePlan ratePlan) {
    36	        Room room = roomRepository.findByNumber(roomNumber)
    37	            .orElseThrow(() -> new RoomNotFoundException(roomNumber));
    38	
    39	        if (guests < 1) {
    40	            throw new InvalidRequestException("Number of guests must be at least 1");
    41	        }
    42	
    43	        if (guests > room.getCapacity()) {
    44	            throw new CapacityExceededException(room.getCapacity(), guests);
    45	        }
    46	
    47	        if (reservationRepository.hasConflict(roomNumber, checkIn, checkOut, null)) {
    48	            throw new RoomUnavailableException(roomNumber, checkIn, checkOut);
    49	        }
    50	
    51	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    52	        BigDecimal subtotal = pricingService.calculateSubtotal(room, checkIn, checkOut);
    53	        BigDecimal discount = pricingService.calculateDiscount(subtotal, ratePlan);
    54	        BigDecimal total = pricingService.calculateTotal(subtotal, discount);
    55	
    56	        Reservation reservation = new Reservation(
    57	            null,
    58	            roomNumber,
    59	            guestName,
    60	            guestEmail,
    61	            guestCpf,
    62	            checkIn,
    63	            checkOut,
    64	            guests,
    65	            ratePlan,
    66	            nights,
    67	            subtotal,
    68	            discount,
    69	            total,
    70	            ReservationStatus.PENDING,
    71	            BigDecimal.ZERO,
    72	            null
    73	        );
    74	
    75	        return reservationRepository.save(reservation);
    76	    }
    77	
    78	    public Reservation confirmReservation(Long id) {
    79	        Reservation reservation = reservationRepository.findById(id)
    80	            .orElseThrow(() -> new ReservationNotFoundException(id));
    81	
    82	        if (!reservation.canConfirm()) {
    83	            throw new OperationNotAllowedException("Cannot confirm reservation in status " + reservation.getStatus());
    84	        }
    85	
    86	        reservation.setStatus(ReservationStatus.CONFIRMED);
    87	        reservation.setAmountPaid(reservation.getTotal());
    88	        Reservation updated = reservationRepository.save(reservation);
    89	
    90	        eventDispatcher.dispatch(new ReservationConfirmedEvent(updated));
    91	
    92	        return updated;
    93	    }
    94	
    95	    public Reservation checkIn(Long id) {
    96	        Reservation reservation = reservationRepository.findById(id)
    97	            .orElseThrow(() -> new ReservationNotFoundException(id));
    98	
    99	        if (!reservation.canCheckIn()) {
   100	            throw new OperationNotAllowedException("Cannot check in reservation in status " + reservation.getStatus());
   101	        }
   102	
   103	        reservation.setStatus(ReservationStatus.CHECKED_IN);
   104	        return reservationRepository.save(reservation);
   105	    }
