   107	    public Reservation checkOut(Long id) {
   108	        Reservation reservation = reservationRepository.findById(id)
   109	            .orElseThrow(() -> new ReservationNotFoundException(id));
   110	
   111	        if (!reservation.canCheckOut()) {
   112	            throw new OperationNotAllowedException("Cannot check out reservation in status " + reservation.getStatus());
   113	        }
   114	
   115	        reservation.setStatus(ReservationStatus.CHECKED_OUT);
   116	        return reservationRepository.save(reservation);
   117	    }
   118	
   119	    public Reservation cancelReservation(Long id) {
   120	        Reservation reservation = reservationRepository.findById(id)
   121	            .orElseThrow(() -> new ReservationNotFoundException(id));
   122	
   123	        if (!reservation.canCancel()) {
   124	            throw new OperationNotAllowedException("Cannot cancel reservation in status " + reservation.getStatus());
   125	        }
   126	
   127	        ReservationStatus previousStatus = reservation.getStatus();
   128	        reservation.setStatus(ReservationStatus.CANCELLED);
   129	
   130	        BigDecimal refund = BigDecimal.ZERO;
   131	        if (previousStatus == ReservationStatus.CONFIRMED && reservation.getRatePlan() == RatePlan.STANDARD) {
   132	            refund = reservation.getAmountPaid();
   133	        }
   134	        reservation.setRefund(refund);
   135	
   136	        Reservation updated = reservationRepository.save(reservation);
   137	
   138	        eventDispatcher.dispatch(new ReservationCancelledEvent(updated, previousStatus));
   139	
   140	        return updated;
