    12	import java.util.Locale;
    13	
    14	public class GuestNotificationHandler implements EventHandler<ReservationConfirmedEvent> {
    15	    private static final Locale PT_BR = Locale.forLanguageTag("pt-BR");
    16	    private static final DateTimeFormatter DATE_FORMAT = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    17	    private static final NumberFormat MONEY_FORMAT = NumberFormat.getCurrencyInstance(PT_BR);
    18	
    19	    private final EmailService emailService;
    20	
    21	    public GuestNotificationHandler(EmailService emailService) {
    22	        this.emailService = emailService;
    23	    }
    24	
    25	    @Override
    26	    public void handle(ReservationConfirmedEvent event) {
    27	        Reservation reservation = event.reservation();
    28	        String receipt = buildReceipt(reservation);
    29	        String body = String.format("""
    30	            Olá, %s!
    31	
    32	            Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
    33	
    34	            %s
    35	
    36	            A entrada é a partir das 14h, e a saída, até as 12h.
    37	            Até breve!""", reservation.getGuestName(), receipt);
    38	
    39	        emailService.send(
    40	            reservation.getGuestEmail(),
    41	            "Reserva confirmada - Pousada Maré Alta",
    42	            body
    43	        );
    44	    }
    45	
    46	    private String buildReceipt(Reservation reservation) {
    47	        StringBuilder sb = new StringBuilder();
    48	        sb.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    49	        sb.append("Hóspede: ").append(reservation.getGuestName())
    50	          .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")").append("\n");
    51	        sb.append("Quarto: ").append(reservation.getRoomNumber()).append(" (")
    52	          .append(getRoomTypeName(reservation.getRoomNumber())).append(")").append("\n");
    53	        sb.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
    54	          .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
    55	          .append(" | ").append(reservation.getNights()).append(reservation.getNights() == 1 ? " diária" : " diárias").append("\n");
    56	        sb.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    57	
    58	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    59	            sb.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    60	        }
    61	
    62	        sb.append("Total: ").append(formatMoney(reservation.getTotal()));
    63	        return sb.toString();
    64	    }
    65	
    66	    private String getRoomTypeName(String roomNumber) {
    67	        return switch (roomNumber) {
    68	            case "101", "102" -> "STANDARD";
    69	            case "201", "202" -> "DELUXE";
    70	            case "301" -> "SUITE";
    71	            default -> "";
    72	        };
    73	    }
    74	
    75	    private String formatDate(LocalDate date) {
    76	        return date.format(DATE_FORMAT);
    77	    }
    78	
    79	    private String formatMoney(BigDecimal amount) {
    80	        return MONEY_FORMAT.format(amount);
    81	    }
    82	
    83	    private String formatCpf(String cpf) {
    84	        if (cpf.length() == 11) {
    85	            return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    86	                   cpf.substring(6, 9) + "-" + cpf.substring(9);
    87	        }
    88	        return cpf;
    89	    }
    90	}
