     1	package com.marealta.infrastructure.notification;
     2	
     3	import com.marealta.domain.event.DomainEvent;
     4	
     5	import java.util.ArrayList;
     6	import java.util.HashMap;
     7	import java.util.List;
     8	import java.util.Map;
     9	
    10	public class EventDispatcher {
    11	    private final Map<Class<? extends DomainEvent>, List<EventHandler<? extends DomainEvent>>> handlers = new HashMap<>();
    12	
    13	    public <T extends DomainEvent> void register(Class<T> eventType, EventHandler<T> handler) {
    14	        handlers.computeIfAbsent(eventType, k -> new ArrayList<>()).add(handler);
    15	    }
    16	
    17	    @SuppressWarnings("unchecked")
    18	    public <T extends DomainEvent> void dispatch(T event) {
    19	        List<EventHandler<? extends DomainEvent>> eventHandlers = handlers.get(event.getClass());
    20	        if (eventHandlers != null) {
    21	            for (EventHandler<? extends DomainEvent> handler : eventHandlers) {
    22	                ((EventHandler<T>) handler).handle(event);
    23	            }
    24	        }
    25	    }
    26	}
